import { Injectable, Logger } from '@nestjs/common';
import { Cron } from '@nestjs/schedule';
import { AlertsService } from '../alerts/alerts.service';

// 1. We explicitly define the shape of the data we want from the API
interface OpenMeteoResponse {
  current_weather?: {
    windspeed: number;
  };
}

@Injectable()
export class WeatherService {
  private readonly logger = new Logger(WeatherService.name);
  private lastWindSpeed = -1;

  constructor(private readonly alertsService: AlertsService) {}

  @Cron('*/10 * * * * *')
  async fetchWeather() {
    try {
      const response = await fetch(
        'https://api.open-meteo.com/v1/forecast?latitude=51.4416&longitude=5.4697&current_weather=true',
      );

      // 2. We cast the 'any' JSON into our strictly typed interface
      const data = (await response.json()) as OpenMeteoResponse;
      const weather = data.current_weather;

      // 3. TypeScript now knows 'windspeed' exists and is a number!
      if (weather && weather.windspeed !== undefined) {
        await this.alertsService.createSystemAlert(
          `Weather trigger: Wind speed changed to ${weather.windspeed} km/h`,
          'WARNING',
        );
      }
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      this.logger.error('Failed to fetch weather data', message);
    }
  }
}
